keyframes.text:
@keyframes sgb-scroll-bounce-chevron {
  0%, 100% { transform: rotate(45deg) translate(0px, 0px); }
  50% { transform: rotate(45deg) translate(4px, 4px); }
}

@keyframes sgb-scroll-bounce-caret {
  0%, 100% { transform: translateX(-50%) rotate(45deg) translate(0px, 0px); }
  50% { transform: translateX(-50%) rotate(45deg) translate(3px, 3px); }
}

@keyframes sgb-scroll-mouse {
  0% { transform: translate(-50%, 0px); opacity: 1; }
  60% { transform: translate(-50%, 12px); opacity: 0; }
  100% { transform: translate(-50%, 0px); opacity: 0; }
}

@keyframes sgb-pulse {
  0%, 100% { opacity: 1; transform: scale(1); }
  50% { opacity: 0.45; transform: scale(0.75); }
}

@keyframes mm-burger-breathe {
  0%, 100% { box-shadow: 0 8px 18px rgba(var(--color-primary-rgb, 213, 21, 34), 0.25),
            inset 0 1px 0 rgba(255, 255, 255, 0.22),
            inset 0 -1px 0 rgba(0, 0, 0, 0.22); }
  50% { box-shadow: 0 12px 30px rgba(var(--color-primary-rgb, 213, 21, 34), 0.55),
            inset 0 1px 0 rgba(255, 255, 255, 0.28),
            inset 0 -1px 0 rgba(0, 0, 0, 0.22); }
}
